package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.servlet.*; import java.io.*; @WebServlet("/challenges") public class ChallengesServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{HttpSession h=r.getSession(false);int id=h!=null&&h.getAttribute("studentId")!=null?(Integer)h.getAttribute("studentId"):0;r.setAttribute("challenges",new CreatorDAO().challenges(id));r.getRequestDispatcher("/WEB-INF/jsp/challenges.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}}
